function npv = priceBumpedSwap(swapInfo, settlementDate, bumpedDates, bumpedDiscounts)
% PRICEBUMPEDSWAP Calculates the Net Present Value of a standard swap under a bumped curve.
%
%   This is a highly optimized helper function designed for finite-difference
%   Delta calculations. It takes the locked-in characteristics of a base swap
%   (specifically its par rate and schedule) and re-prices it using a freshly
%   bootstrapped, shocked yield curve.
%
%   INPUTS:
%       swapInfo        : A struct containing the fixed characteristics of the
%                         swap, generated by buildStandardSwap. Must contain:
%                           - .paymentDates (array of fixed leg payment dates)
%                           - .tau (array of year fractions for the fixed leg)
%                           - .parRate (the locked-in base par rate)
%       settlementDate  : The valuation date (t0) used as the anchor for interpolation.
%       bumpedDates     : Array of dates from the re-bootstrapped (bumped) curve.
%       bumpedDiscounts : Array of discount factors corresponding to bumpedDates.
%
%   OUTPUTS:
%       npv             : The exact Net Present Value of the Receiver Swap
%                         (receives fixed, pays floating) under the bumped curve,
%                         assuming a 1-unit (1 EUR) notional.

% Interpolate new discount factors for the swap's specific payment dates
dfs_bumped = getDiscountFactorByZeroRatesLinearInterp( ...
    settlementDate, swapInfo.paymentDates, bumpedDates, bumpedDiscounts);

% Ensure column vector for matrix multiplication/element-wise operations
dfs_bumped = dfs_bumped(:);

% Exact bumped NPV of Receiver Swap (Fixed Leg - Floating Leg)
% Fixed Leg: Par Rate * BPV
bumpedFixed = swapInfo.parRate * sum(swapInfo.tau .* dfs_bumped);

% Floating Leg: 1 - B(t0, tN) 
bumpedFloat = 1 - dfs_bumped(end);

% Total Net Present Value
npv = bumpedFixed - bumpedFloat;

end